Error RendererRD::ExternalLinkedOwnerTest::staged_instance192_resource_count(uint32_t capacity, uint32_t surfaces, uint32_t &count) {
	ExternalOutputStorage::Instance192Layout layout;
	const Error sized = ExternalOutputStorage::plan_instance192(capacity, surfaces, layout);
	if (sized == OK) {
		count = layout.resource_count;
	}
	return sized;
}

Error RendererRD::ExternalLinkedOwnerTest::staged_guard_snapshot(ParticlesStorage &storage, RID rid, uint32_t index,
		uint64_t generation, GDExtensionDeviceExit::Registry &registry, GDExtensionProductionRequestRefV1 request,
		uint64_t ordinal, uint64_t lease, Dictionary &out) {
	if (!GDExtensionDeviceExit::Registry::Lock::owns(registry)) {
		return ERR_UNAUTHORIZED;
	}
	const auto *particles = storage.particles_owner.get_or_null(rid);
	if (!particles || !particles->external || index >= particles->external->slot_count) {
		return ERR_INVALID_DATA;
	}
	const auto &owner = *particles->external;
	const auto &slot = owner.slots[index];
	if (!owner.device || owner.device != RenderingDevice::get_singleton() || !owner.device->native_immutable_is_render_thread() ||
			owner.generation != generation || slot.original_registry != &registry ||
			slot.original_request.registry_instance != request.registry_instance || slot.original_request.handle_serial != request.handle_serial ||
			slot.original_action_ordinal != ordinal || !lease || slot.lease_serial != lease) {
		return ERR_INVALID_DATA;
	}
	out["particles"] = int64_t(rid.get_id());
	out["generation"] = int64_t(owner.generation);
	out["request"] = int64_t(slot.original_request.handle_serial);
	out["registry_instance"] = int64_t(slot.original_request.registry_instance);
	out["acquire_ordinal"] = int64_t(slot.original_action_ordinal);
	out["slot"] = index;
	out["lease"] = int64_t(slot.lease_serial);
	out["slot_state"] = uint32_t(slot.state);
	out["guard_owned_group"] = int64_t(slot.guard_owned_group);
	out["owned_group"] = int64_t(slot.owned_group);
	out["guard_proof_installed"] = slot.guard_proof_payload != nullptr;
	out["guard_proof_bytes"] = slot.guard_proof_bytes;
	out["guard_resources_ready"] = slot.guard_resources_ready;
	out["retained_host_snapshot"] = slot.retained_host_snapshot;
	out["surface_count"] = slot.surface_count;
	out["generation_config_inline"] = owner.generation_config_inline;
	out["generation_mesh_count"] = owner.generation_mesh_count;
	out["generation_material_count"] = owner.generation_material_count;
	out["generation_surfaces_complete"] = owner.generation_surfaces_complete;
	out["config_surfaces_size"] = owner.config.surfaces.size();
	out["config_surface_materials_size"] = owner.config.surface_materials.size();
	out["view_capacity"] = owner.view_capacity;
	out["read_capacity"] = owner.read_capacity;
	out["surface_capacity"] = owner.surface_capacity;
	out["binding_capacity"] = owner.binding_capacity;
	out["storage_capacity"] = owner.storage_capacity;
	out["preparation_capacity"] = owner.preparation_capacity;
	out["metadata_bytes"] = int64_t(owner.metadata_lease.get_size());
	Array guard_sets;
	uint32_t guard_set_count = 0;
	for (RID guard_set : slot.guard_uniform_sets) {
		guard_sets.push_back(int64_t(guard_set.get_id()));
		guard_set_count += guard_set.is_valid();
	}
	out["guard_uniform_sets"] = guard_sets;
	out["guard_uniform_set_count"] = guard_set_count;
	Array owned_storage;
	if (slot.storage) {
		for (const auto &resource : slot.storage->resources) {
			Dictionary entry;
			entry["rid"] = int64_t(resource.rid.get_id());
			entry["bytes"] = resource.bytes;
			owned_storage.push_back(entry);
		}
	}
	out["owned_storage"] = owned_storage;
	return OK;
}

Error RendererRD::ExternalLinkedOwnerTest::staged_color_snapshot(ParticlesStorage &storage, RID rid, uint32_t index,
		const Ref<RendererViewport::Viewport::CameraCapture> &capture, Dictionary &out, RID &pipeline, uint32_t &draw, uint32_t &close) {
	const auto *particles = storage.particles_owner.get_or_null(rid);
	out["particles"] = int64_t(rid.get_id());
	out["slot"] = index;
	out["particles_found"] = particles != nullptr;
	out["external_owner_found"] = particles && particles->external;
	if (!particles || !particles->external) {
		out["snapshot_detail"] = "original_external_owner_missing";
		return ERR_DOES_NOT_EXIST;
	}
	const auto &owner = *particles->external;
	out["owner_slot_count"] = owner.slot_count;
	if (index >= owner.slot_count) {
		out["snapshot_detail"] = "original_slot_out_of_range";
		return ERR_PARAMETER_RANGE_ERROR;
	}
	const auto &slot = owner.slots[index];
	const auto source_report = [&capture](const auto &source) {
		Dictionary value;
		value["present"] = source.is_valid();
		value["same_ref"] = source.is_valid() && source == capture;
		if (source.is_valid()) {
			const auto &token = source->get_token();
			value["viewport"] = int64_t(source->get_viewport().get_id());
			value["camera"] = int64_t(source->get_invocation().camera.get_id());
			value["view_id"] = int64_t(token.view_id);
			value["view_epoch"] = int64_t(token.view_epoch);
			value["capture_ordinal"] = int64_t(token.capture_ordinal);
			value["present_seq"] = int64_t(source->get_presentation_key().present_seq);
		}
		return value;
	};
	out["expected_camera_source"] = source_report(capture);
	out["slot_camera_source"] = source_report(slot.native_camera_source);
	out["slot_state"] = uint32_t(slot.state);
	out["slot_request"] = int64_t(slot.original_request.handle_serial);
	out["slot_lease"] = int64_t(slot.lease_serial);
	out["slot_publication_closed"] = slot.publication_closed;
	out["slot_pass_uses_closed"] = slot.pass_uses_closed;
	out["color_serial"] = int64_t(slot.native_color_consumption_serial);
	out["color_empty"] = slot.native_color_empty;
	out["read_serial"] = int64_t(slot.native_color_read_serial);
	out["read_cell"] = slot.native_color_read_cell;
	out["slot_color_close_graph"] = slot.native_color_close_graph;
	out["color_token"] = String::hex_encode_buffer(slot.native_color_consumption_token.bytes, 32);
	out["owner_read_capacity"] = owner.read_capacity;
	out["owner_read_cells_present"] = owner.read_cells != nullptr;
	out["owner_next_view_serial"] = int64_t(owner.next_view_serial);
	out["owner_next_read_serial"] = int64_t(owner.next_read_serial);
	out["owner_preparation_capacity"] = owner.preparation_capacity;
	out["slot_preparation_reserved_count"] = slot.preparation_reserved_count;
	out["slot_preparation_selected_count"] = slot.preparation_selected_count;
	Array preparations;
	if (owner.preparation_rows) {
		for (uint32_t i = 0; i < owner.preparation_capacity; ++i) {
			const auto &row = owner.preparation_rows[i];
			if (!owner.preparation_bank_row_matches(index, i, row)) {
				continue;
			}
			Dictionary entry;
			entry["index"] = i;
			entry["tuple_state"] = uint32_t(row.tuple_state);
			entry["surface"] = row.tuple_surface;
			entry["pass"] = uint32_t(row.selection.pass);
			entry["version"] = row.selection.version;
			entry["view_count"] = row.selection.view_count;
			entry["backend_error"] = row.backend_error;
			entry["finish_error"] = row.finish_error;
			entry["finish_complete"] = row.finish_complete;
			entry["pipeline_sealed"] = row.pipeline_sealed;
			entry["pipeline"] = int64_t(row.created_pipeline.get_id());
			entry["transforms_set"] = int64_t(row.transforms_uniform_set.get_id());
			entry["material_hold_active"] = row.material.is_active();
			if (row.material.is_active()) {
				const auto &material = row.material.get_snapshot();
				entry["material_shader"] = int64_t(material.shader.get_id());
				entry["material_set_index"] = material.uniform_set_index;
				entry["material_set"] = int64_t(material.uniform_set.get_id());
				entry["material_uniform_bytes"] = material.uniform_bytes.size();
				entry["material_texture_count"] = material.textures.size();
			}
			if (row.selected_geometry < 2 && row.geometry[row.selected_geometry].has_retained_snapshot()) {
				entry["index_array"] = int64_t(row.geometry[row.selected_geometry].get_retained_index_array().get_id());
			}
			preparations.push_back(entry);
		}
	}
	out["original_preparation_rows"] = preparations;
	Array surfaces;
	if (slot.surfaces) {
		for (uint32_t i = 0; i < slot.surface_count; ++i) {
			const auto &surface = slot.surfaces[i];
			Dictionary entry;
			entry["surface"] = i;
			entry["draw_graph"] = surface.color_draw_graph;
			entry["close_graph"] = surface.color_close_graph;
			entry["empty_close_graph"] = surface.color_empty_close_graph;
			surfaces.push_back(entry);
		}
	}
	out["surface_color_graphs"] = surfaces;
	Array reads;
	if (owner.read_cells) {
		for (uint32_t i = 0; i < owner.read_capacity; ++i) {
			const auto &cell = owner.read_cells[i];
			if (cell.slot != index && i != slot.native_color_read_cell) {
				continue;
			}
			Dictionary entry;
			entry["index"] = i;
			entry["slot"] = cell.slot;
			entry["serial"] = int64_t(cell.serial);
			entry["state"] = uint32_t(cell.state);
			entry["consumer_present"] = cell.consumer != nullptr;
			entry["camera_source"] = source_report(cell.camera_source);
			entry["raster_bound"] = cell.raster_bound;
			entry["draw_accepted"] = cell.draw_accepted;
			entry["capture_complete"] = cell.capture_complete;
			entry["uncaptured_effect"] = cell.uncaptured_effect;
			entry["draw_graph"] = cell.draw_graph;
			entry["close_graph"] = cell.close_graph;
			entry["preparation"] = cell.preparation;
			entry["graph_count"] = cell.graph_count;
			entry["graph_limit"] = cell.graph_limit;
			reads.push_back(entry);
		}
	}
	out["original_read_cells"] = reads;
	if (!slot.native_color_consumption_serial) {
		out["snapshot_detail"] = "original_color_receipt_missing";
		return ERR_INVALID_DATA;
	}
	if (slot.native_color_empty) {
		out["snapshot_detail"] = "original_color_receipt_empty";
		return ERR_INVALID_DATA;
	}
	if (!owner.read_cells || slot.native_color_read_cell >= owner.read_capacity) {
		out["snapshot_detail"] = "original_color_read_index_out_of_range";
		return ERR_PARAMETER_RANGE_ERROR;
	}
	if (slot.native_camera_source != capture) {
		out["snapshot_detail"] = "original_slot_camera_source_mismatch";
		return ERR_INVALID_DATA;
	}
	const auto &cell = owner.read_cells[slot.native_color_read_cell];
	if (cell.serial != slot.native_color_read_serial) {
		out["snapshot_detail"] = "original_color_read_serial_mismatch";
		return ERR_INVALID_DATA;
	}
	if (cell.camera_source != capture || !cell.raster_bound || !cell.draw_accepted || !cell.capture_complete ||
			cell.close_graph != slot.native_color_close_graph || !owner.preparation_rows || cell.preparation >= owner.preparation_capacity) {
		out["snapshot_detail"] = "original_color_read_state_mismatch";
		return ERR_INVALID_DATA;
	}
	const auto &preparation = owner.preparation_rows[cell.preparation];
	pipeline = preparation.created_pipeline;
	draw = cell.draw_graph;
	close = cell.close_graph;
	out["draw_graph"] = draw;
	out["close_graph"] = close;
	out["graph_count"] = cell.graph_count;
	out["graph_limit"] = cell.graph_limit;
	out["pipeline"] = int64_t(pipeline.get_id());
	out["present_seq"] = int64_t(cell.camera_key.present_seq);
	out["raster_bound"] = cell.raster_bound;
	out["draw_accepted"] = cell.draw_accepted;
	out["capture_complete"] = cell.capture_complete;
	out["list_begin_frame"] = int64_t(cell.list_begin.graph_frame);
	out["list_begin_instance"] = int64_t(cell.list_begin.graph_instance);
	return OK;
}
