			test.check(__LINE__, request.control.state == ProductionControlState::OWNER_CONSUMED);
			test.check(__LINE__, registry.production_observe(ref, &expired, &report).native_error == OK);
			test.check(__LINE__, request.control.state == ProductionControlState::OWNER_CONSUMED && request.next_control_serial == busy_serial + 1);
			receipt_check(GDEXTENSION_PRODUCTION_CONTROL_RECEIPT_OWNER_CONSUMED_V1, busy_serial, true);
			test.check(__LINE__, fixture.driver.retains == 1 && fixture.driver.polls == 1);
			// The same public Unavailable result can also be an already consumed
			// RT result. The server fixture temporarily removes its actual driver
			// only while this original FIFO turn executes, then restores it.
			test.check(__LINE__, registry.production_observe(ref, &budget, &report).native_error == ERR_BUSY);
			const uint64_t unavailable_serial = request.control.serial;
			test.rendezvous();
			receipt_check(GDEXTENSION_PRODUCTION_CONTROL_RECEIPT_RETURNED_V1, unavailable_serial, true);
			test.check(__LINE__, request.control.output.result.native_error == ERR_UNAVAILABLE);
			test.check(__LINE__, registry.production_observe(ref, &budget, &report).native_error == ERR_UNAVAILABLE);
			receipt_check(GDEXTENSION_PRODUCTION_CONTROL_RECEIPT_OWNER_CONSUMED_V1, unavailable_serial, true);
