	struct NativeCameraReadyProbe {
		SingletonEnrollment *fixture = nullptr;
		Callable callable;
		GDExtensionDeviceExit::NormalRelayToken relay;
		GDExtensionProductionCameraSampleV1 received{};
		uint32_t calls = 0, ordinary_calls = 0, frees = 0;
		Thread::ID free_thread = 0;
		uint64_t outer_frame = 0;
		static void ordinary(void *opaque, const GDExtensionConstVariantPtr *, GDExtensionInt, GDExtensionVariantPtr returned, GDExtensionCallError *error) {
			++static_cast<NativeCameraReadyProbe *>(opaque)->ordinary_calls;
			*reinterpret_cast<Variant *>(returned) = Variant();
			*error = { GDEXTENSION_CALL_OK, 0, 0 };
		}
		static void free(void *opaque) {
			auto &p = *static_cast<NativeCameraReadyProbe *>(opaque);
			++p.frees;
			p.free_thread = Thread::get_caller_id();
		}
		static void other(void *, GDExtensionProductionAttachmentRefV1, const GDExtensionProductionCameraSampleV1 *) {}
		static void scene(void *, const GDExtensionNativeScenePhaseV1 *, GDExtensionProductionRequestRefV1, const GDExtensionProductionOperationV1 *) {}
		static void other_scene(void *, const GDExtensionNativeScenePhaseV1 *, GDExtensionProductionRequestRefV1, const GDExtensionProductionOperationV1 *) {}
		static void typed(void *opaque, GDExtensionProductionAttachmentRefV1 attachment, const GDExtensionProductionCameraSampleV1 *sample) {
			using namespace GDExtensionDeviceExit;
			auto &p = *static_cast<NativeCameraReadyProbe *>(opaque);
			++p.calls;
			REQUIRE(sample != nullptr);
			p.received = *sample;
			CHECK(attachment.registry_instance == p.fixture->attachment.registry_instance);
			CHECK(attachment.handle_serial == p.fixture->attachment.handle_serial);
			CHECK(p.fixture->rd.native_immutable_is_render_thread());
			const auto *entry = RegistrationContext::current;
			REQUIRE(entry != nullptr);
			CHECK(entry->admitted);
			CHECK(entry->frame_id != p.outer_frame);
			CHECK(entry->reference->registry == &p.fixture->registry);
			CHECK(entry->reference->slot == p.fixture->reference.slot);
			// This is a normal protected leaf, not an accepted RECORD scope.
			CHECK(Registry::production_physical_frame == nullptr);
			NormalRelaySnapshot active;
			REQUIRE(p.fixture->registry.observe_normal_relay(p.relay, active) == OK);
			CHECK(active.active_deliveries == 1);
			CHECK_FALSE(active.cell_released);
			CHECK_FALSE(active.holder_closed);
			CHECK(p.fixture->registry.camera_ready_call_relay(attachment, *sample) == ERR_BUSY);
			// The request was actually released before entry. No child/mailbox
			// can accidentally supply this attachment destruction barrier.
			CHECK(p.fixture->registry.production_close(attachment).native_error == ERR_BUSY);
			CHECK(p.fixture->registry.cancel_normal_relay(p.relay) == OK);
			CHECK(p.fixture->registry.release_normal_relay_holder(p.relay) == ERR_BUSY);
			CHECK(p.fixture->registry.forget_normal_relay(p.relay) == ERR_BUSY);
			CHECK(p.frees == 0);
			REQUIRE(p.fixture->registry.observe_normal_relay(p.relay, active) == OK);
			CHECK(active.active_deliveries == 1);
			CHECK(active.cancelled);
			CHECK(active.release_requested);
			CHECK_FALSE(active.cell_released);
		}
	};
