				const auto &row = *probe.contended_row;
				CHECK(row.finish_error == OK);
				CHECK(row.geometry_adopted);
				CHECK(row.material_adopted);
				CHECK(row.pipeline_sealed);
				CHECK(row.geometry_transferred[0]);
