				CHECK(row.owned_pipeline_root == probe.contended_pipeline);
				const auto *pipeline_after = fixture.rd.render_pipeline_owner.get_or_null(probe.contended_pipeline);
				const auto *geometry_after = fixture.rd.vertex_array_owner.get_or_null(probe.contended_geometry);
				CHECK((pipeline_after != nullptr && geometry_after != nullptr));
				if (pipeline_after) { CHECK(pipeline_after->native_immutable_holds == 2); }
				if (geometry_after) { CHECK(geometry_after->native_immutable_holds == 1); }
				uint32_t sealed_groups = 0;
				for (uint32_t i = output_request->use_count + output_request->binding_used; i < output_request->capacity.resource_uses; ++i) {
					const auto &cell = output_request->uses[i];
					if (cell.output_role == ProductionUseCell::OutputRole::DISPOSAL_GROUP && cell.disposal_group_serial == row.pipeline_owned_group) {
						++sealed_groups;
						CHECK(cell.disposal_group_native_hold);
						CHECK(cell.disposal_group_native_hold_count == 1);
						CHECK_FALSE(cell.disposal_group_release);
						CHECK_FALSE(cell.disposal_group_dropped);
					}
				}
				CHECK(sealed_groups == 1);
				// Adoption moves the existing G/M holds. First owned-pipeline seal
				// adds its keeper beside the material borrower, hence one new hold.
				CHECK(fixture.rd.native_immutable_hold_count == probe.contended_holds + 1);
				CHECK(fixture.driver.raster_frees == 0);
